using FintechApp.Entities;
using FintechApp.Interfaces.Repositories;
using FintechApp.Interfaces.Services;
using FintechApp.Requests.PaymentGateway;
using FintechApp.Responses.PaymentGateway;
using FintechApp.StaticModels;
namespace FintechApp.Services
{
    public class PaymentGatewayService : IPaymentGatewayService
    {
        private readonly IPaymentGatewayRepository _repository;
        public PaymentGatewayService(IPaymentGatewayRepository repository) { _repository = repository; }
        private static PaymentGatewayResponse MapToResponse(PaymentGateway e) => new() { PaymentGatewayID = e.PaymentGatewayID, UserID = e.UserID, OrderID = e.OrderID, Amount = e.Amount, GatewayCharge = e.GatewayCharge, Commission = e.Commission, WalletID = e.WalletID, Status = e.Status, TransactionID = e.TransactionID, PayMode = e.PayMode, Response = e.Response, PaymentProviderID = e.PaymentProviderID, IsUpdate = e.IsUpdate, OpeningBalance = e.OpeningBalance, ClosingBalance = e.ClosingBalance, Remark = e.Remark, DistributerUserID = e.DistributerUserID, SuperDistributerUserID = e.SuperDistributerUserID, DistributerCommission = e.DistributerCommission, SuperDistributerCommission = e.SuperDistributerCommission, RetailerTDS = e.RetailerTDS, DistributerTDS = e.DistributerTDS, SuperDistributerTDS = e.SuperDistributerTDS, AdminGST = e.AdminGST, ReferenceID = e.ReferenceID, ServiceID = e.ServiceID, PaymentStatus = e.PaymentStatus, DateTime = e.DateTime, UpdatedateTime = e.UpdatedateTime };
        public async Task<List<PaymentGatewayResponse>> GetAll() { var list = await _repository.GetAll(); return list.Select(MapToResponse).ToList(); }
        public async Task<PaymentGatewayResponse?> GetByID(int id) { var e = await _repository.GetByID(id); return e == null ? null : MapToResponse(e); }
        public async Task<List<PaymentGatewayResponse>> GetByUserID(int userid) { var list = await _repository.GetByUserID(userid); return list.Select(MapToResponse).ToList(); }
        public async Task<string> Create(CreatePaymentGatewayRequest request) { var entity = new PaymentGateway { UserID = request.UserID, OrderID = request.OrderID, Amount = request.Amount, GatewayCharge = request.GatewayCharge, Commission = request.Commission, WalletID = request.WalletID, Status = request.Status, TransactionID = request.TransactionID, PayMode = request.PayMode, Response = request.Response, PaymentProviderID = request.PaymentProviderID, IsUpdate = request.IsUpdate, OpeningBalance = request.OpeningBalance, ClosingBalance = request.ClosingBalance, Remark = request.Remark, DistributerUserID = request.DistributerUserID, SuperDistributerUserID = request.SuperDistributerUserID, DistributerCommission = request.DistributerCommission, SuperDistributerCommission = request.SuperDistributerCommission, RetailerTDS = request.RetailerTDS, DistributerTDS = request.DistributerTDS, SuperDistributerTDS = request.SuperDistributerTDS, AdminGST = request.AdminGST, ReferenceID = request.ReferenceID, ServiceID = request.ServiceID, PaymentStatus = request.PaymentStatus, }; await _repository.Insert(entity); return StatusType.Ok; }
        public async Task<string> Update(UpdatePaymentGatewayRequest request) { var entity = await _repository.GetByID(request.PaymentGatewayID); if (entity == null) return Messages.PaymentGatewayMessages.NotFound; entity.UserID = request.UserID; entity.OrderID = request.OrderID; entity.Amount = request.Amount; entity.GatewayCharge = request.GatewayCharge; entity.Commission = request.Commission; entity.WalletID = request.WalletID; entity.Status = request.Status; entity.TransactionID = request.TransactionID; entity.PayMode = request.PayMode; entity.Response = request.Response; entity.PaymentProviderID = request.PaymentProviderID; entity.IsUpdate = request.IsUpdate; entity.OpeningBalance = request.OpeningBalance; entity.ClosingBalance = request.ClosingBalance; entity.Remark = request.Remark; entity.DistributerUserID = request.DistributerUserID; entity.SuperDistributerUserID = request.SuperDistributerUserID; entity.DistributerCommission = request.DistributerCommission; entity.SuperDistributerCommission = request.SuperDistributerCommission; entity.RetailerTDS = request.RetailerTDS; entity.DistributerTDS = request.DistributerTDS; entity.SuperDistributerTDS = request.SuperDistributerTDS; entity.AdminGST = request.AdminGST; entity.ReferenceID = request.ReferenceID; entity.ServiceID = request.ServiceID; entity.PaymentStatus = request.PaymentStatus; await _repository.Update(entity); return StatusType.Ok; }
        public async Task<string> Delete(int id) { int result = await _repository.Delete(id); return result > 0 ? StatusType.Ok : Messages.PaymentGatewayMessages.NotFound; }
    }
}
